@Observable @MainActor
final class LoginBloc {
    private(set) var state = State()
    private var observers: [AsyncStream<State>.Continuation] = []

    func send(_ event: Event) {
        state = reduce(state, event)            // observable property write
        for o in observers { o.yield(state) }   // async-sequence consumers
    }
    func states() -> AsyncStream<State> {
        AsyncStream { c in observers.append(c); c.yield(state) }
    }
}
